class TestCase_8(ATTestCase.TestCase):
    testCaseDesc = "From the endpoint in subnet <C>, send 100 Echo Requests to <XA>. Capture the replies on the endpoint. Read the DUT's output packet counters on both link ports before and after with show interface <port>."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33242, 9002.33242.8'
    ckNeeds = ['ifAddrMap']
    skipIfExcl = True
    testCaseMethod = "From the endpoint in subnet <C>, send 100 Echo Requests to <XA>. Capture the replies on the endpoint. Read the DUT's output packet counters on both link ports before and after with show interface <port>.\n"
    testCaseMethod += "Verify: All 100 requests get replies with matching identifier and sequence number. Every reply's IP source is <XA>, never <YA>. The output packet count on the DUT's link-B port rises by at least 100, and the link-A port's count rises by less than 100. Together these show that the replies left through link-B.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # The endpoint needs an address in subnet C on the testbox interface.
        self.srcIp = ethA.get_ipv4_addr(2)
        tb.cmd('ip addr add {}/{} dev {}'.format(self.srcIp, ethA.ipv4subnetPrefix, ethA.name))

    def main(self):
        # legacy 6902_ATPyLib_training/test-6901.1001.py lines 97-171
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        self.log("STEP 11: From the endpoint in subnet <C>, send 100 Echo Requests to <XA>. Capture the replies on the endpoint. Read the DUT's output packet counters on both link ports before and after with show interface <port>.")
        ifAddrMap = getattr(self.testSet, 'ifAddrMap', None)
        if not ifAddrMap or not ifAddrMap.get('vlanA') or not ifAddrMap.get('vlanB'):
            self.supported = False
            self.failed('ifAddrMap (vlanA/vlanB addresses) was not established by TestCase_2')
            return
        xa = ifAddrMap['vlanA'].split('/')[0]
        ya = ifAddrMap['vlanB'].split('/')[0]
        srcIp = getattr(self, 'srcIp', None) or ethA.get_ipv4_addr(2)
        dutMac = portA.get_mac_addr()
        ident = 0x3324
        count = 100

        def out_pkts(port):
            dutA.mode('#')
            text = dutA.cmd('show interface {}'.format(port.name))
            match = re.search(r'output packets\s+(\d+)', text)
            return int(match.group(1)) if match else None

        beforeA = out_pkts(portA)
        beforeB = out_pkts(portPeer)
        pkts = [Ether(src=ethA.macAddr, dst=dutMac) / IP(src=srcIp, dst=xa) /
                ICMP(type=8, id=ident, seq=seq) for seq in range(1, count + 1)]
        subProc = tb.start_tcpdump(ethA.name, 'icmp_echo_xa.pcap', 'icmp')
        sendp(pkts, iface=ethA.name, verbose=0, inter=0.02)
        time.sleep(3)
        recPkts = tb.stop_tcpdump(subProc)
        afterA = out_pkts(portA)
        afterB = out_pkts(portPeer)

        replySeqs = set()
        badSrc = []
        wrongId = 0
        for pkt in recPkts:
            if pkt.haslayer(ICMP) and pkt.haslayer(IP) and pkt[ICMP].type == 0 and pkt[IP].dst == srcIp:
                if pkt[ICMP].id != ident:
                    wrongId += 1
                    continue
                if pkt[IP].src != xa:
                    badSrc.append(pkt[IP].src)
                replySeqs.add(pkt[ICMP].seq)
        output = 'replies={} unique_seq={} bad_src={} wrong_id={} A:{}->{} B:{}->{}'.format(
            len(recPkts), len(replySeqs), badSrc[:3], wrongId, beforeA, afterA, beforeB, afterB)
        self.log('OBSERVED: {}'.format(output))

        if len(replySeqs & set(range(1, count + 1))) == count:
            self.passed('All {} echo requests got replies with matching id {} and sequence numbers'.format(count, ident))
        else:
            self.failed('Only {} of {} echo requests got replies with matching id/seq'.format(len(replySeqs), count))

        if not badSrc and replySeqs:
            self.passed('Every reply had IP source {}, none from {}'.format(xa, ya))
        else:
            self.failed('Reply IP source not {} (saw {}, {} replies seen)'.format(xa, badSrc[:3], len(replySeqs)))

        if None in (beforeA, afterA, beforeB, afterB):
            self.failed('Could not read output packet counters: A {}->{}, B {}->{}'.format(
                beforeA, afterA, beforeB, afterB))
            return
        riseA = afterA - beforeA
        riseB = afterB - beforeB
        if riseB >= count:
            self.passed('Link-B port {} output packets rose by {}'.format(portPeer.name, riseB))
        else:
            self.failed('Link-B port {} output packets rose by only {}, expected at least {}'.format(
                portPeer.name, riseB, count))
        if riseA < count:
            self.passed('Link-A port {} output packets rose by {} (< {})'.format(portA.name, riseA, count))
        else:
            self.failed('Link-A port {} output packets rose by {}, expected less than {}'.format(
                portA.name, riseA, count))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        srcIp = getattr(self, 'srcIp', None)
        if srcIp:
            tb.cmd('ip addr del {}/{} dev {}'.format(srcIp, ethA.ipv4subnetPrefix, ethA.name))
        dutA.mode('#')


class TestCase_9(ATTestCase.TestCase):
    testCaseDesc = 'Repeat step 11 with the loopback address <L1> as the target: send 100 Echo Requests from the endpoint in subnet <C>, capture the replies and read the link-port counters.'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33242, 9002.33242.9'
    ckNeeds = ['ifAddrMap']
    skipIfExcl = True
    testCaseMethod = 'Repeat step 11 with the loopback address <L1> as the target: send 100 Echo Requests from the endpoint in subnet <C>, capture the replies and read the link-port counters.\n'
    testCaseMethod += 'Verify: All 100 requests get replies sourced from <L1>, never <YA> or <XA>. The output count on the link-B port rises by at least 100.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # Per-case PRECONDITIONS: the testbox endpoint needs a /32 route to the loopback
        # address via the DUT address that sits in the endpoint's subnet (config only).
        self.l1 = None
        self.gw = None
        addr_map = getattr(self.testSet, 'ifAddrMap', None)
        if not addr_map or not addr_map.get('lo'):
            return
        self.l1 = addr_map['lo'].split('/')[0]
        endpoint_net = '.'.join(str(ethA.ipv4addr).split('.')[:3])
        for if_type, addr in addr_map.items():
            if if_type == 'lo' or not addr:
                continue
            host = addr.split('/')[0]
            if '.'.join(host.split('.')[:3]) == endpoint_net:
                self.gw = host
                break
        if self.gw is not None:
            tb.cmd('ip route replace {}/32 via {} dev {}'.format(self.l1, self.gw, ethA.name))

    def main(self):
        # legacy 6902_ATPyLib_training/test-6901.1001.py lines 97-171
        # AI sonnet 2026-10-12 (reply-source check adapted from ART 1340_past_issues_2 TestCase_64237)
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        self.log('STEP 12: Repeat step 11 with the loopback address <L1> as the target: send 100 Echo Requests from the endpoint in subnet <C>, capture the replies and read the link-port counters.')
        addr_map = getattr(self.testSet, 'ifAddrMap', None)
        if not addr_map or not addr_map.get('lo'):
            self.supported = False
            self.failed('ifAddrMap (loopback address) was not established by TestCase_2')
            return
        if self.gw is None:
            self.failed('No DUT address in the endpoint subnet {} to route to the loopback {}'.format(
                ethA.ipv4addr, self.l1))
            return
        l1 = self.l1
        forbidden = []
        for if_type in ('vlanA', 'vlanB'):
            if addr_map.get(if_type):
                forbidden.append(addr_map[if_type].split('/')[0])

        # Counter used for the "output count rises" check: the port the replies leave the DUT on.
        # Replies return towards the endpoint, i.e. out of the port facing the testbox link.
        counter_re = re.compile(r'Output packets\s+(\d+)', re.IGNORECASE)
        dutA.mode('#')
        before_out = dutA.cmd('show interface {}'.format(portA.name))
        match_before = counter_re.search(before_out)
        if match_before is None:
            self.failed('Cannot find an Output packets counter for {} before the test'.format(portA.name))
            self.log(before_out)
            return
        out_before = int(match_before.group(1))

        sub_proc = tb.start_tcpdump(ethA.name, 'icmp_lo_step12.pcap', 'icmp')
        tb.cmd('ping -c 100 -i 0.2 -W 2 -I {} {}'.format(ethA.name, l1))
        time.sleep(2)
        pkts = tb.stop_tcpdump(sub_proc)

        dutA.mode('#')
        after_out_text = dutA.cmd('show interface {}'.format(portA.name))
        match_after = counter_re.search(after_out_text)

        from_l1 = 0
        from_forbidden = 0
        from_other = 0
        for pkt in pkts:
            if pkt.haslayer(ICMP) and pkt.haslayer(IP) and pkt[ICMP].type == 0:
                src = pkt[IP].src
                if src == l1:
                    from_l1 += 1
                elif src in forbidden:
                    from_forbidden += 1
                else:
                    from_other += 1
        out_after = int(match_after.group(1)) if match_after else None
        output = 'replies from {}: {}, from {}: {}, from other: {}, {} Output packets {} -> {}'.format(
            l1, from_l1, forbidden, from_forbidden, from_other, portA.name, out_before, out_after)
        self.log('OBSERVED: {}'.format(output))

        if from_l1 == 100:
            self.passed('All 100 Echo Requests got replies sourced from loopback {}'.format(l1))
        else:
            self.failed('Only {} of 100 replies were sourced from loopback {}'.format(from_l1, l1))
        if from_forbidden == 0 and from_other == 0:
            self.passed('No replies sourced from {} or any other address'.format(forbidden))
        else:
            self.failed('{} replies sourced from {} and {} from other addresses, expected none'.format(
                from_forbidden, forbidden, from_other))
        if out_after is None:
            self.failed('Cannot find an Output packets counter for {} after the test'.format(portA.name))
        elif out_after - out_before >= 100:
            self.passed('{} output count rose by {} (>= 100)'.format(portA.name, out_after - out_before))
        else:
            self.failed('{} output count rose by only {}, expected at least 100'.format(
                portA.name, out_after - out_before))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # Mirror configure(): remove the testbox route to the loopback address.
        if getattr(self, 'l1', None) and getattr(self, 'gw', None):
            tb.cmd('ip route del {}/32 via {} dev {}'.format(self.l1, self.gw, ethA.name))
        dutA.mode('#')


