class TestCase_22(ATTestCase.TestCase):
    testCaseDesc = 'Apply no shutdown to the test port and poll show interface <test port> status until the row reads connected (timeout 60 s). Then send 10 Echo Requests to each address in liveAddrs (step 23) and each address in staleAddrs (step 23).'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33242, 9002.33242.22'
    ckNeeds = ['liveAddrs', 'staleAddrs']
    skipIfExcl = True
    testCaseMethod = 'Apply no shutdown to the test port and poll show interface <test port> status until the row reads connected (timeout 60 s). Then send 10 Echo Requests to each address in liveAddrs (step 23) and each address in staleAddrs (step 23).\n'
    testCaseMethod += "Verify: The test port's row reads connected. Every address in liveAddrs replies, each reply sourced from the requested address. No address in staleAddrs gets a reply, and no reply is sourced from any stale address.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        self.host_routes = []

    def main(self):
        # ART 1346_swi_misc/test-1346.1001.py lines 389-425
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        self.log('STEP 25: Apply no shutdown to the test port and poll show interface <test port> status until the row reads connected (timeout 60 s). Then send 10 Echo Requests to each address in liveAddrs (step 23) and each address in staleAddrs (step 23).')
        liveAddrs = getattr(self.testSet, 'liveAddrs', None)
        staleAddrs = getattr(self.testSet, 'staleAddrs', None)
        if liveAddrs is None:
            self.supported = False
            self.failed('liveAddrs was not established by TestCase_20')
            return
        if staleAddrs is None:
            self.supported = False
            self.failed('staleAddrs was not established by TestCase_20')
            return

        def as_text(out):
            if isinstance(out, (tuple, list)):
                return '\n'.join(str(x) for x in out)
            return str(out)

        # Bring the test port up and poll its status row
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no shutdown')
        dutA.mode('#')
        row = None
        deadline = time.time() + 60
        while True:
            status = dutA.cmd('show interface status', log=False)
            row = next((line for line in status.splitlines() if line.split()[:1] == [portA.name]), None)
            if row is not None and 'connected' in row and 'notconnect' not in row:
                break
            if time.time() >= deadline:
                break
            time.sleep(3)
        port_up = row is not None and 'connected' in row and 'notconnect' not in row

        # Send 10 echo requests to every live and stale address from the testbox
        results = {}
        self.host_routes = getattr(self, 'host_routes', [])
        for kind, addrs in (('live', liveAddrs), ('stale', staleAddrs)):
            for addr in addrs:
                tb.cmd('ip route replace {}/32 dev {}'.format(addr, ethA.name))
                self.host_routes.append(addr)
                ping_out = as_text(tb.cmd('ping -n -c 10 -i 0.5 -W 2 -I {} {}'.format(ethA.name, addr)))
                sources = re.findall(r'bytes from ([0-9.]+):', ping_out)
                results[addr] = (kind, sources)
        output = 'row={!r}; '.format(row) + '; '.join(
            '{} {} replies={} sources={}'.format(kind, addr, len(srcs), sorted(set(srcs)))
            for addr, (kind, srcs) in results.items())
        self.log('OBSERVED: {}'.format(output))

        if not port_up:
            self.failed('{} row did not read connected within 60 s: {}'.format(portA.name, row))
            return
        self.passed('{} row reads connected: {}'.format(portA.name, row.strip()))

        all_stale_sources = set()
        for addr in staleAddrs:
            all_stale_sources.update(results[addr][1])
        for addr in liveAddrs:
            srcs = results[addr][1]
            if len(srcs) > 0 and set(srcs) == {addr}:
                self.passed('live address {} replied {} times, all sourced from {}'.format(addr, len(srcs), addr))
            elif len(srcs) == 0:
                self.failed('live address {} got no echo reply'.format(addr))
            else:
                self.failed('live address {} replies were sourced from {}, expected only {}'.format(
                    addr, sorted(set(srcs)), addr))
        for addr in staleAddrs:
            srcs = results[addr][1]
            if len(srcs) == 0:
                self.passed('stale address {} got no echo reply'.format(addr))
            else:
                self.failed('stale address {} got {} echo replies sourced from {}'.format(
                    addr, len(srcs), sorted(set(srcs))))
        leaked = set()
        for addr in liveAddrs:
            leaked.update(set(results[addr][1]) & set(staleAddrs))
        if leaked or (all_stale_sources and not set(staleAddrs) >= all_stale_sources):
            self.failed('replies were sourced from stale addresses: {}'.format(sorted(leaked or all_stale_sources)))
        elif not all_stale_sources:
            self.passed('no echo reply was sourced from any stale address {}'.format(sorted(staleAddrs)))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        for addr in getattr(self, 'host_routes', []):
            tb.cmd('ip route del {}/32 dev {}'.format(addr, ethA.name))
        self.host_routes = []
        dutA.mode('#')


class TestCase_23(ATTestCase.TestCase):
    testCaseDesc = "Run copy running-config startup-config, then reboot('', timeOut=900) and mode('#'). Wait until the test port's row in show interface <test port> status reads connected. Read show ip interface brief, then send 10 Echo Requests to each address in liveAddrs and staleAddrs (step 23)."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33242, 9002.33242.23'
    ckNeeds = ['liveAddrs', 'staleAddrs']
    skipIfExcl = True
    testCaseMethod = "Run copy running-config startup-config, then reboot('', timeOut=900) and mode('#'). Wait until the test port's row in show interface <test port> status reads connected. Read show ip interface brief, then send 10 Echo Requests to each address in liveAddrs and staleAddrs (step 23).\n"
    testCaseMethod += 'Verify: After the reload, show ip interface brief lists exactly the addresses in liveAddrs, on the same interfaces, and none from staleAddrs. Every address in liveAddrs replies, each reply sourced from the requested address with matching identifier, sequence number and payload. Addresses in staleAddrs get no reply, and no reply is sourced from them.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # The addresses under test are published by earlier cases; their interface
        # mapping is not known here, so nothing is configured by this step.
        pass

    def main(self):
        # SVT 3002_platform_reboot/library_3002.py lines 67-106
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        self.log("STEP 26: Run copy running-config startup-config, then reboot('', timeOut=900) and mode('#'). Wait until the test port's row in show interface <test port> status reads connected. Read show ip interface brief, then send 10 Echo Requests to each address in liveAddrs and staleAddrs (step 23).")
        import re

        liveAddrs = getattr(self.testSet, 'liveAddrs', None)
        staleAddrs = getattr(self.testSet, 'staleAddrs', None)
        if liveAddrs is None:
            self.supported = False
            self.failed('liveAddrs was not established by TestCase_20')
            return
        if staleAddrs is None:
            self.supported = False
            self.failed('staleAddrs was not established by TestCase_20')
            return
        liveAddrs = list(liveAddrs)
        staleAddrs = list(staleAddrs)

        def parse_brief(text):
            pairs = set()
            for line in text.splitlines():
                tok = line.split()
                if len(tok) >= 2:
                    addr = tok[1].split('/')[0]
                    if re.match(r'^\d+\.\d+\.\d+\.\d+$', addr):
                        pairs.add((tok[0], addr))
            return pairs

        # Pre-reload state, so "same interfaces" can be checked after the reload
        dutA.mode('#')
        preBrief = dutA.cmd('show ip interface brief')
        prePairs = parse_brief(preBrief)

        # Save, reload
        dutA.cmd('copy running-config startup-config')
        dutA.reboot('', timeOut=900)
        dutA.mode('#')

        # Wait for the test port to read connected
        connected = False
        statusOut = ''
        for attempt in range(40):
            statusOut = dutA.cmd('show interface {} status'.format(portA.name), log=False)
            row = next((line for line in statusOut.splitlines() if line.split()[:1] == [portA.name]), None)
            if row is not None and 'connected' in row.split() and 'notconnect' not in row:
                connected = True
                break
            time.sleep(10)
        if not connected:
            self.failed('{} did not read connected after reload: {}'.format(portA.name, statusOut.strip()[-200:]))
            return
        self.passed('{} reads connected after the reload'.format(portA.name))

        # Address table after reload
        dutA.mode('#')
        postBrief = dutA.cmd('show ip interface brief')
        postPairs = parse_brief(postBrief)
        postAddrs = set(addr for (ifc, addr) in postPairs)

        # Echo Requests from the testbox
        mac = getattr(dutA, 'macAddr', None)
        if not mac:
            ifOut = dutA.cmd('show interface {}'.format(portA.name), log=False)
            m = re.search(r'address is ([0-9a-fA-F]{4})\.([0-9a-fA-F]{4})\.([0-9a-fA-F]{4})', ifOut)
            if m:
                hexs = ''.join(m.groups())
                mac = ':'.join(hexs[i:i + 2] for i in range(0, 12, 2))
        srcIp = getattr(ethA, 'ipv4addr', None)
        if not srcIp:
            srcIp = ethA.get_ipv4_addr(0)
        srcMac = getattr(ethA, 'macAddr', None)

        allAddrs = liveAddrs + staleAddrs
        expect = {}
        pkts = []
        if mac and srcIp:
            for idx, addr in enumerate(allAddrs):
                ident = 0x2300 + idx
                payload = ('ck23-{:02d}-'.format(idx) + 'abcdefghijklmnopqrstuvwxyz')[:32].encode()
                expect[addr] = (ident, payload)
                for seq in range(1, 11):
                    if srcMac:
                        eth = Ether(src=srcMac, dst=mac)
                    else:
                        eth = Ether(dst=mac)
                    pkts.append(eth / IP(src=srcIp, dst=addr) /
                                ICMP(type=8, id=ident, seq=seq) / Raw(load=payload))

        replies = []
        if pkts:
            sub = tb.start_tcpdump(ethA.name, 'icmp_reload_{}.pcap'.format(self.testCaseName),
                                   'icmp and dst host {}'.format(srcIp))
            sendp(pkts, iface=ethA.name, verbose=0, inter=0.05)
            time.sleep(3)
            recPkts = tb.stop_tcpdump(sub)
            for pkt in recPkts:
                if pkt.haslayer(IP) and pkt.haslayer(ICMP) and pkt[ICMP].type == 0:
                    replies.append(pkt)

        goodCount = {}
        badFields = []
        staleSeen = []
        for pkt in replies:
            src = pkt[IP].src
            if src in staleAddrs:
                staleSeen.append(src)
                continue
            if src not in expect:
                continue
            ident, payload = expect[src]
            load = bytes(pkt[Raw].load) if pkt.haslayer(Raw) else b''
            if pkt[ICMP].id == ident and 1 <= pkt[ICMP].seq <= 10 and load == payload:
                goodCount.setdefault(src, set()).add(pkt[ICMP].seq)
            else:
                badFields.append('{} id={} seq={}'.format(src, pkt[ICMP].id, pkt[ICMP].seq))

        output = 'pre-reload: {}\npost-reload brief:\n{}\nreplies from live: {}\nreplies from stale: {}'.format(
            sorted(prePairs), postBrief, dict((a, len(s)) for a, s in goodCount.items()), staleSeen)
        self.log('OBSERVED: {}'.format(output))

        # Checkpoint 1: address table lists exactly liveAddrs, none from staleAddrs
        missing = sorted(set(liveAddrs) - postAddrs)
        extra = sorted(postAddrs - set(liveAddrs))
        staleListed = sorted(postAddrs & set(staleAddrs))
        if not missing and not extra and not staleListed:
            self.passed('show ip interface brief lists exactly liveAddrs {} and no staleAddrs'.format(sorted(liveAddrs)))
        else:
            self.failed('show ip interface brief mismatch: missing {}, unexpected {}, stale listed {}'.format(
                missing, extra, staleListed))

        # Checkpoint 2: same interfaces as before the reload
        if prePairs and postPairs == prePairs:
            self.passed('Addresses are on the same interfaces after reload: {}'.format(sorted(postPairs)))
        else:
            self.failed('Interface/address pairs changed over reload: before {}, after {}'.format(
                sorted(prePairs), sorted(postPairs)))

        # Checkpoint 3: every live address replies with correct fields
        if not pkts:
            self.failed('Could not build Echo Requests: DUT mac {} testbox ip {}'.format(mac, srcIp))
            return
        noReply = [a for a in liveAddrs if len(goodCount.get(a, ())) < 10]
        if not noReply and not badFields:
            self.passed('All {} live addresses replied to all 10 Echo Requests with matching source, id, seq and payload'.format(
                len(liveAddrs)))
        else:
            self.failed('Live address reply problems: incomplete replies from {}, mismatched replies {}'.format(
                noReply, badFields[:5]))

        # Checkpoint 4: stale addresses get no reply
        if not staleSeen:
            self.passed('No Echo Reply sourced from any stale address {}'.format(sorted(staleAddrs)))
        else:
            self.failed('Echo Replies received from stale addresses: {}'.format(sorted(set(staleSeen))))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        # main() changed no running-config; leave the console in exec mode.
        dutA.mode('#')


